'use strict';
const assert = require('node:assert');
const api = require('./solution');
assert.deepStrictEqual(Object.keys(api), ['selectPage']);
const { selectPage } = api;

const pages = {
  '': 'home',
  users: 'users page',
  'users/detail': 'detail page',
  '/internal/': 'literal slash key'
};
const before = { ...pages };
assert.strictEqual(selectPage('', pages), 'home');
assert.strictEqual(selectPage('/', pages), 'home');
assert.strictEqual(selectPage('////', pages), 'home');
assert.strictEqual(selectPage('/users/', pages), 'users page');
assert.strictEqual(selectPage('////users////', pages), 'users page');
assert.strictEqual(selectPage('///users/detail///', pages), 'detail page');
assert.strictEqual(selectPage('users//detail', pages), null);
assert.strictEqual(selectPage('/missing/', pages), null);
assert.deepStrictEqual(pages, before);

const inherited = Object.create({ inherited: 'prototype page' });
inherited.own = 'own page';
assert.strictEqual(selectPage('own', inherited), 'own page');
assert.strictEqual(selectPage('inherited', inherited), null);
const nullPrototype = Object.create(null);
nullPrototype.x = 'X';
assert.strictEqual(selectPage('/x/', nullPrototype), 'X');

for (const route of [null, undefined, 3, {}]) {
  assert.throws(() => selectPage(route, pages), TypeError);
}
for (const invalidPages of [null, undefined, [], 'pages', { good: 'yes', bad: 1 }]) {
  assert.throws(() => selectPage('/good/', invalidPages), TypeError);
}

